<script setup lang="ts">import { ref } from 'vue';import { api } from '../../api';import EligibilityList from '../../components/common/EligibilityList.vue';const loading=ref(false);const result=ref<any>(null);async function run(){loading.value=true;result.value=await api.eligibility({province:'河南',score:620,subject_type:'物理类'});loading.value=false}</script><template><section class="content-page"><div class="eyebrow">PATHWAY / CHECK</div><h1>路径资格自检</h1><p class="lede">游客也可以先进行演示自检；正式资格以服务端规则和官方审核为准。</p><button class="primary" :disabled="loading" @click="run">{{loading?'检查中…':'开始自检 ↗'}}</button><EligibilityList v-if="result?.results" :results="result.results"/><div v-else class="state-box">填写条件后查看结果。</div></section></template>
